INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11627, 52736, 'tt0087385', NULL, 'Hardbodies', 'Hardbodies', 'movie', 1984, 'https://image.tmdb.org/t/p/w500/9z7lbMRQSbcohiPV7WzMbTqhbnI.jpg', 'https://image.tmdb.org/t/p/original/9RFB5EfVoJk7dR5i3Buk8kRe1z8.jpg', 'Three middle-aged daddies visit California to have a marvelous time at the beach. When they learn that a nice apartment and an expensive cabriolet isn''t enough for them to score with the chicks, they employ a student to help them. At first he''s as disgusted of them and his job as his girlfriend, but soon they find out how to use the situation to everyone''s benefit.', NULL, NULL, 2.1302, 4.815, 0, 1.01, '2026-08-24 01:47:08', '2026-08-24 01:47:08');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11628, 20075, 'tt0082163', NULL, 'Nice Dreams', 'Nice Dreams', 'movie', 1981, 'https://image.tmdb.org/t/p/w500/r9rsnbe3R9WtjzIhwajHVft9Fp3.jpg', 'https://image.tmdb.org/t/p/original/mtdd7jmJhutdsIyqVRSjsK1PetX.jpg', 'Nice Dreams - it rhymes with ice creams. And that''s what Cheech and Chong are selling in this thoroughly wacky comedy. The outrageous, permanently spaced-out duo sells enough of their "specially mixed" ice cream to take the cash and realize their fondest dreams: new guitars, islands in the sun and beautiful women. But, of course, not everything goes as planned. While celebrating their wealth in a new wave Chinese restaurant, Cheech meets his long-lost love Donna, and promptly escorts her to her posh penthouse. He soon learns, however, that Donna''s boyfriend, an ex-con named Animal, is on his way to her boudoir. Meanwhile, Chong has unwittingly exchanged all their money for a worthless bank check - and the only way to get it back is to escape into a nearby insane asylum.', NULL, NULL, 2.342, 5.8, 0, 1.06, '2026-08-24 01:47:08', '2026-08-24 01:47:08');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11629, 328595, 'tt3479316', NULL, 'Parallels', 'Parallels', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/fqUallsX9KSSey1tw7AbujlOmOa.jpg', 'https://image.tmdb.org/t/p/original/4GbCLy8uia4nwc39CHOT0XHjnpY.jpg', 'An underground MMA fighter must confront his sister and his past in an adventure through parallel universes', NULL, NULL, 1.4695, 6.034, 0, 9.07, '2026-08-24 01:47:08', '2026-08-24 01:47:08');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11630, 41972, 'tt0080768', NULL, 'Virus', '復活の日', 'movie', 1980, 'https://image.tmdb.org/t/p/w500/hUkLBDDUISSEv19xXRj2tFWNzMj.jpg', 'https://image.tmdb.org/t/p/original/zxUm7SBcU7ewjYVDceW8ihWAoRi.jpg', 'Scientists in Antarctica desperately try to find a cure to a military virus that was released in a plane crash and has wiped out the rest of the world.', NULL, NULL, 2.4503, 6.3, 0, 1.07, '2026-08-24 01:47:08', '2026-08-24 01:47:08');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11631, 793961, 'tt13829262', NULL, 'Rubikon', 'Rubikon', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/n5Ynx568yHn1hKG2ND7ctoL9jEl.jpg', 'https://image.tmdb.org/t/p/original/4IJemTO3UP7vuYjqhhfVLQ9yl3w.jpg', 'The company soldier Hannah and the scientists Gavin and Dimitri are researching an algae project on board the Rubikon space station, which is supposed to permanently supply humanity with oxygen and food. But suddenly the earth disappears below them in a brown, toxic fog and all contact is broken off - are they the last survivors of humanity? Should they initiate the safe station, dare the return flight and thereby risk their lives?', NULL, NULL, 2.4162, 5.329, 0, 1.03, '2026-08-24 01:47:08', '2026-08-24 01:47:08');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11632, 382212, 'tt5450084', NULL, 'Homo Sapiens', 'Homo Sapiens', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/evpIbLI8ebs0jMLntcMt6tv1yc1.jpg', 'https://image.tmdb.org/t/p/original/8wt2qyeon5kPXZNmKOVV36OOIMe.jpg', 'HOMO SAPIENS is visionary documentarian Nikolaus Geyrhalter''s exploration of the finiteness and fragility of human existence, the end of the industrial age, and what it means to be a human being. What will remain of our lives after we''re gone? Empty spaces, ruins, cities, increasingly overgrown with vegetation, crumbling asphalt: the areas we currently inhabit, now abandoned and decaying, gradually reclaimed by nature. Comprised of a succession of eerily depopulated, dystopian landscapes from across the world, HOMO SAPIENS offers an at once mesmerizing and chilling vision of what a posthuman future might look like.', NULL, NULL, 0.8027, 7.0, 0, 1.13, '2026-08-24 01:47:08', '2026-08-24 01:47:08');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11633, 559581, 'tt9203694', NULL, 'Stowaway', 'Stowaway', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/eFyRjhJfhNgM565U2mwEp5YUUOv.jpg', 'https://image.tmdb.org/t/p/original/cBGQMVohebbWfmEGdezjyOdW7MO.jpg', 'A three-person crew on a mission to Mars faces an impossible choice when an unplanned passenger jeopardizes the lives of everyone on board.', NULL, NULL, 4.1875, 6.026, 0, 1.07, '2026-08-24 01:47:08', '2026-08-24 01:47:08');
