INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11643, 67654, 'tt0025477', NULL, 'The Mascot', 'Fétiche', 'movie', 1933, 'https://image.tmdb.org/t/p/w500/ntOnxz6FNfLrE74NbYNasM3mNgz.jpg', 'https://image.tmdb.org/t/p/original/5UobGqdn4ETxSTIbsWSFTLpBK3L.jpg', 'A toy stuffed dog has just been sewn together when it hears a young child ask for an orange. The child''s mother explains that they have no money, and so she cannot buy any oranges. The dog is then packed up along with a box full of other toys to be sold, but it soon winds up in the street. The dog picks up an orange from a curb side stand, and hopes to take it home to the child. But that night, before the dog can get back to the child''s home, it must face a series of strange and frightening adventures.', NULL, NULL, 1.0652, 7.0, 0, 1.01, '2026-08-24 01:47:08', '2026-08-24 01:47:08');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11644, 77604, 'tt0142666', NULL, 'Momotaro, Sacred Sailors', '桃太郎 海の神兵', 'movie', 1945, 'https://image.tmdb.org/t/p/w500/sbSbqtsNBfUDBzQtpm35R6pHhzi.jpg', 'https://image.tmdb.org/t/p/original/wiUSAqNR0gCXrZ4J8vJ46Xfw9Ms.jpg', 'The first Japanese feature-length animated film. It was directed by Mitsuyo Seo, who was ordered to make a propaganda film for the war by the Japanese Naval Ministry. Shochiku Moving Picture Laboratory shot the 74-minute film in 1944 and screened it on April 12, 1945. It is a sequel to Momotarō no Umiwashi, a 37-minute film released in 1943 by the same director. It is black and white. The whole movie also depicts the Japanese "liberation of Asia", as proclaimed by the Government at the time. Seo tried to give dreams to children, as well as to instill the hope for peace, with hidden movie''s hints of dreams and hopes, under the appearance of war propaganda.', NULL, NULL, 0.8996, 4.639, 0, 1.06, '2026-08-24 01:47:08', '2026-08-24 01:47:08');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11645, 1550747, NULL, NULL, 'Tales from Soda Island: The School Trip', 'Tales from Soda Island: The School Trip', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/qrz6mTgjVKqXcHHhEskXQg2QelE.jpg', NULL, 'Behold the marvels of Sodian science! Follow a single drop of glucose rain on a transformative journey across the island as the complex ecosystem processes it into a deliciously sweet carbonated beverage.  Available in many flavors or all of them at once.', NULL, NULL, 0.6103, 0.0, 0, 8.51, '2026-08-24 01:47:08', '2026-08-24 01:47:08');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11646, 396508, 'tt3719434', NULL, 'Encounter', 'Encounter', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/eAzNiaacSJtYrSy6Cps8z3adkC3.jpg', 'https://image.tmdb.org/t/p/original/susEYC6PAabxzEJ9he80zMMAMaA.jpg', 'A newlywed couple Ted and Lauren rent an old farm house to do a thesis on orbs and set up cameras, Strange ghostly noises and haunting occur at night. Ted sees video of Lauren, possessed and wandering the fields at night. When their roommate kills himself they decide to do a séance to see what is haunting the house. Little do they know what they hear and fear is nothing they can pray away.', NULL, NULL, 1.0117, 3.7, 0, 9.17, '2026-08-24 01:47:08', '2026-08-24 01:47:08');
