INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11671, 58833, 'tt0086420', NULL, 'So Long, Stooge', 'Tchao Pantin', 'movie', 1983, 'https://image.tmdb.org/t/p/w500/1D9o6nZDPhB0utyahu5WiSlKMLl.jpg', 'https://image.tmdb.org/t/p/original/noGOjlooQTwSeUTg0lhpnLQWkf4.jpg', 'In the 18th Arrondissement of Paris, Lambert, an aloof garage manager working the night shift at a petrol station spends his time drinking on the job, content in his own company. One night, Bensoussan, a small-time drug pusher in dire straits falls in on a stolen moped pretending to need a spark plug. The two men develop an unlikely friendship.', NULL, NULL, 1.2272, 7.361, 0, 1.02, '2026-08-24 01:47:08', '2026-08-24 01:47:08');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11672, 9898, 'tt0756672', NULL, 'The Killing Floor', 'The Killing Floor', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/mq7X4O63QKoL69gR80eyrPvSsop.jpg', 'https://image.tmdb.org/t/p/original/6wx03fPCeR2zcTMxJJJU29fgxUt.jpg', 'A literary agent moves into a penthouse apartment. Soon after the move, he receives crime scene photographs that seem to have taken place in his new apartment. Next he receives a series of stalker videotapes that document his every move.', NULL, NULL, 1.37, 5.271, 0, 1.02, '2026-08-24 01:47:08', '2026-08-24 01:47:08');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11673, 76768, 'tt0191085', NULL, 'The Devil In The Flesh', 'Il diavolo nella carne', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/oy6R3y26TWo1Tp5T7XIxenN2zWV.jpg', 'https://image.tmdb.org/t/p/original/jeZWjrTI8IWKlHspnPSbLjbdSNi.jpg', 'Dough-crazed mercenaries Sammy and Klaus are on a mission to escort the seriously ill prime minister of a South American country that has just been taken over by the rebels to his buddies over the border. Chased by the rebels, and with the politician''s health rapidly deteriorating, they stumble onto an infirmary staffed by a quartet of nurses and take them hostage, forcing them to cure the prime minister, and fast. After an initial rape, romantic feelings begin to emerge as Helga has it off with Klaus, Katrin with Sammy, and Sophie with Hellen...until a squadron of rebels drops in.', NULL, NULL, 1.4599, 2.8, 0, 1.02, '2026-08-24 01:47:08', '2026-08-24 01:47:08');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11674, 429416, 'tt5974030', NULL, 'The Jesus Rolls', 'The Jesus Rolls', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/wxXZXYNn1H5eVRbpTZVFvWBvjlY.jpg', 'https://image.tmdb.org/t/p/original/7B7s3wrr7fjoGOOURIfGmRH8F07.jpg', 'Hours after his release from prison, Jesus Quintana pairs up with fellow misfits Petey and Marie for a freewheeling joyride of petty crime and romance.', NULL, NULL, 2.3746, 4.389, 0, 1.03, '2026-08-24 01:47:08', '2026-08-24 01:47:08');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11675, 1410, 'tt2070791', NULL, 'Revolution', 'Revolution', 'tv', 2012, 'https://image.tmdb.org/t/p/w500/pNyg4V6kuDstSSxk6Q9GgaBn4B8.jpg', 'https://image.tmdb.org/t/p/original/2wCN49piyT6El4TQZrMy3YGkI7l.jpg', 'One day, electricity just stopped working and the world was suddenly thrust back into the dark ages. Now, 15 years later, a young woman''s life is dramatically changed when a local militia arrives and kills her father, who mysteriously—and unbeknownst to her—had something to do with the blackout. An unlikely group sets out off on a daring journey to find answers about the past in the hopes of reclaiming the future.', NULL, NULL, 14.6534, 6.436, 0, 1.01, '2026-08-24 01:47:08', '2026-08-24 01:47:08');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11676, 20497, 'tt1083845', NULL, 'Ballet Shoes', 'Ballet Shoes', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/sG1ef5gIObTeItweZZxhSLJVs8B.jpg', 'https://image.tmdb.org/t/p/original/vHC79hM1bQG5JR9E8nlZn3pwyPt.jpg', 'An unusual explorer named Gum and his kindly niece adopt three orphans -- Pauline, Petrova and Posy -- and raise them as sisters in 1930s London. But the girls must fend for themselves when Gum doesn''t return from one of his adventures. Together, they nurture their passions for acting, aviation and ballet in this charming TV adaptation of Noel Streatfield''s novel.', NULL, NULL, 2.5313, 6.3, 0, 1.03, '2026-08-24 01:47:08', '2026-08-24 01:47:08');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11677, 1537, 'tt0264472', NULL, 'Changing Lanes', 'Changing Lanes', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/8wh9WzTKo5pJw3EgHYWA60W7Kbl.jpg', 'https://image.tmdb.org/t/p/original/lCPOmWoqtmVrI2yUNUw8iaOaTJn.jpg', 'A rush-hour fender-bender on New York City''s crowded FDR Drive, under most circumstances, wouldn''t set off a chain reaction that could decimate two people''s lives. But on this day, at this time, a minor collision will turn two complete strangers into vicious adversaries. Their means of destroying each other might be different, but their goals, ultimately, will be the same: Each will systematically try to dismantle the other''s life in a reckless effort to reclaim something he has lost.', NULL, NULL, 4.4859, 6.281, 0, 9.02, '2026-08-24 01:47:08', '2026-08-24 01:47:08');
