INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11685, 529862, 'tt7671064', NULL, 'Brittany Runs a Marathon', 'Brittany Runs a Marathon', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/aSWePCEtLpNdD7ykW6OuZqvVhyn.jpg', 'https://image.tmdb.org/t/p/original/zVBsGrA8MIx7DNeo33Ll86dKzZU.jpg', 'Hilarious and outgoing, Brittany Forgler, is everybody’s best friend ― except her own. Her partying, underemployment and toxic relationships are catching up with her. She receives a startling wake-up call when a visit to the doctor reveals how unhealthy she is. Motivated to lose weight, but too broke for a gym and too proud to ask for help, Brit is at a loss, until her neighbor pushes her to run one sweaty block. Soon, she sets an almost unthinkable goal: the New York City Marathon.', NULL, NULL, 1.9965, 6.633, 0, 9.015, '2026-08-24 01:47:08', '2026-08-24 01:47:08');
