INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11691, 13537, 'tt0323944', NULL, 'Shattered Glass', 'Shattered Glass', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/bIFJ49tk79hiFr9Z6bF6QapTg66.jpg', 'https://image.tmdb.org/t/p/original/u4OUSKeFwuP1z42dL58Mi0LYwIg.jpg', 'Stephen Glass is a staff writer for the respected current events and policy magazine The New Republic and a freelance feature writer for publications such as Rolling Stone, Harper''s and George. By the mid-90s, Glass'' articles had turned him into one of the most sought-after young journalists in Washington, but a bizarre chain of events - chronicled in Buzz Bissinger''s September 1998 Vanity Fair article - suddenly stopped his career in its tracks.', NULL, NULL, 4.6959, 6.982, 0, 1.0129999999999999e+01, '2026-08-24 01:47:08', '2026-08-24 01:47:08');
