INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11793, 1721898, NULL, NULL, 'ALMA', 'ALMA', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/g4QiqGTyLvBxjqO3fSIHkIZmT5j.jpg', 'https://image.tmdb.org/t/p/original/gtxAALGcjDI4ptZyAQaWm0ohLom.jpg', 'A non-narrative short film tracking the movement of a flock of women through a megalithic landscape. They appear to be working, enacting a cryptic ceremony with a sense of calm & purposeful labor. A score weaving together their breath & hums with sounds collected from the landscape: wind, Rattlesnake grass & their hands rubbing against stone. The women''s gestures come from both work & dance – evoking the strange overlap between labor & ritual. This film began as a response to the physicality of daily life as a mother & the rhythm of these acts; the relentless repetition of parenting, working, tending the world with our bodies. This repetition can easily become vacant labor, but it can also transform into a kind of meditative, even transcendent ritual, a collective communion with the landscape & each other. ALMA offers itself as a companion piece to McKenna’s photographic rubbings, a glimpse into the same world from where her art arises.', NULL, NULL, 0.5715, 9.0, 0, 1.01, '2026-08-24 01:47:08', '2026-08-24 01:47:08');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11794, 343112, 'tt3584354', NULL, 'Man Vs.', 'Man Vs.', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/k7neRfPEhjruZIBg99Sqs0yBVUk.jpg', 'https://image.tmdb.org/t/p/original/6Ur2AfJX7i83WaxkLTWNgoArGQN.jpg', 'As host of his own hit TV series, ''MAN VS'', Doug Woods is forced to fend for himself for five days in remote locations with no crew, food, or water, only the cameras he carries on his back to film his experiences. Doug''s in the remote woods for a routine episode, until he''s awoken by an earth-shaking crash. Things get weirder as it becomes clear Doug isn''t alone. Someone or something is watching him.', NULL, NULL, 1.1531, 5.489, 0, 1.01, '2026-08-24 01:47:08', '2026-08-24 01:47:08');
