UPDATE "recommendations" SET "tmdb_id"=201085, "imdb_id"='tt2554274', "igdb_id"=NULL, "title"='Crimson Peak', "original_title"='Crimson Peak', "media_type"='movie', "release_year"=2015, "poster_url"='https://image.tmdb.org/t/p/w500/f9TOb5anVwZeSbYjU1qNxPk3KUk.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/nQQIUwEEqa6sjPvnqcGbjJxbdit.jpg', "overview"='In the aftermath of a family tragedy, an aspiring author is torn between love for her childhood friend and the temptation of a mysterious outsider. Trying to escape the ghosts of her past, she is swept away to a house that breathes, bleeds… and remembers.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.5712, "vote_average"=6.7, "is_ambiguous"=0, "evidence_score"=7.36588235294117623e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-24 01:47:08' WHERE "id"=4;
UPDATE "recommendations" SET "tmdb_id"=120, "imdb_id"='tt0120737', "igdb_id"=NULL, "title"='The Lord of the Rings: The Fellowship of the Ring', "original_title"='The Lord of the Rings: The Fellowship of the Ring', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/6oom5QYQ2yQTMJIbnvbkBL9cHo6.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/mWDdRXTivGE7aaY2vo1Ie0PfCX5.jpg', "overview"='Young hobbit Frodo Baggins, after inheriting a mysterious ring from his uncle Bilbo, must leave his home in order to keep it from falling into the hands of its evil creator. Along the way, a fellowship is formed to protect the ringbearer and make sure that the ring arrives at its final destination: Mt. Doom, the only place where it can be destroyed.', "external_url"=NULL, "platforms"=NULL, "popularity"=47.6819, "vote_average"=8.439, "is_ambiguous"=0, "evidence_score"=7.28933823529411739e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-24 01:47:08' WHERE "id"=5;
