UPDATE "recommendations" SET "tmdb_id"=14442, "imdb_id"='tt0327679', "igdb_id"=NULL, "title"='Ella Enchanted', "original_title"='Ella Enchanted', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/7AyNzwSEpJEG1gBdgwRfXi1cjs8.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/r4Q7GKzTiAzr1MGU1b13s9L12YZ.jpg', "overview"='Ella lives in a magical world in which each child, at the moment of their birth, is given a virtuous "gift" from a fairy godmother. Ella''s so-called gift, however, is obedience. This birthright proves itself to be quite the curse once Ella finds herself in the hands of several unscrupulous characters whom she quite literally cannot disobey. Determined to gain control of her life and decisions, Ella sets off on a journey to find her fairy godmother who she hopes will lift the curse. The path, however, isn''t easy -- Ella must outwit a slew of unpleasant obstacles including ogres, giants, wicked stepsisters, elves and Prince Charmont''s evil uncle, who wants to take over the crown and rule the kingdom.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.5962, "vote_average"=6.482, "is_ambiguous"=0, "evidence_score"=1.67255555555555552e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-24 01:47:08' WHERE "id"=233;
