UPDATE "recommendations" SET "tmdb_id"=34647, "imdb_id"='tt1191111', "igdb_id"=NULL, "title"='Enter the Void', "original_title"='Enter the Void', "media_type"='movie', "release_year"=2010, "poster_url"='https://image.tmdb.org/t/p/w500/krKnsfvSJM1PL40tLicRhVQ6kuG.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/2Mlw0JRNZHXLYxbeJ0LmiCCTiok.jpg', "overview"='This psychedelic tour of life after death is seen entirely from the point of view of Oscar, a young American drug dealer and addict living in Tokyo with his prostitute sister, Linda. When Oscar is killed by police during a bust gone bad, his spirit journeys from the past -- where he sees his parents before their deaths -- to the present -- where he witnesses his own autopsy -- and then to the future, where he looks out for his sister from beyond the grave.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.365, "vote_average"=7.3, "is_ambiguous"=0, "evidence_score"=1.33667286821705431e+02, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-24 01:47:08' WHERE "id"=1017;
