UPDATE "recommendations" SET "tmdb_id"=17654, "imdb_id"='tt1136608', "igdb_id"=NULL, "title"='District 9', "original_title"='District 9', "media_type"='movie', "release_year"=2009, "poster_url"='https://image.tmdb.org/t/p/w500/tuGlQkqLxnodDSk6mp5c2wvxUEd.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/jhM3wgWUrrOkz9r4xwV5cV5RhI4.jpg', "overview"='Thirty years ago, aliens arrive on Earth. Not to conquer or give aid, but to find refuge from their dying planet. Separated from humans in a South African area called District 9, the aliens are managed by Multi-National United, which is unconcerned with the aliens'' welfare but will do anything to master their advanced technology. When a company field agent contracts a mysterious virus that begins to alter his DNA, there is only one place he can hide: District 9.', "external_url"=NULL, "platforms"=NULL, "popularity"=14.4222, "vote_average"=7.475, "is_ambiguous"=0, "evidence_score"=4.55614634146341472e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-24 01:47:08' WHERE "id"=1176;
UPDATE "recommendations" SET "tmdb_id"=8224, "imdb_id"='tt0134273', "igdb_id"=NULL, "title"='8MM', "original_title"='8MM', "media_type"='movie', "release_year"=1999, "poster_url"='https://image.tmdb.org/t/p/w500/mhr9xRpjOBqlBjgDwtiOx6FsLvV.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/eEP8pyCmldfbnml0SFMvPK7kE4x.jpg', "overview"='A small, seemingly innocuous plastic reel of film leads surveillance specialist Tom Welles down an increasingly dark and frightening path. With the help of the streetwise Max, he relentlessly follows a bizarre trail of evidence to determine the fate of a complete stranger. As his work turns into obsession, he drifts farther and farther away from his wife, family and simple life as a small-town PI.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.5241, "vote_average"=6.5, "is_ambiguous"=0, "evidence_score"=1.81182352941176496e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-24 01:47:08' WHERE "id"=1186;
UPDATE "recommendations" SET "tmdb_id"=8839, "imdb_id"='tt0112642', "igdb_id"=NULL, "title"='Casper', "original_title"='Casper', "media_type"='movie', "release_year"=1995, "poster_url"='https://image.tmdb.org/t/p/w500/2ah8fNJFZVU3vcXhU5xfAYi2eym.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/sQPckU0TfSeYIlUneHfIXwzQC2f.jpg', "overview"='Casper is a kind young ghost who peacefully haunts a mansion in Maine. When specialist James Harvey arrives to communicate with Casper and his fellow spirits, he brings along his teenage daughter, Kat. Casper quickly falls in love with Kat, but their budding relationship is complicated not only by his transparent state, but also by his troublemaking apparition uncles and their mischievous antics.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.8993, "vote_average"=6.342, "is_ambiguous"=0, "evidence_score"=1.53491666666666652e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-24 01:47:08' WHERE "id"=1189;
