UPDATE "recommendations" SET "tmdb_id"=97020, "imdb_id"='tt1234721', "igdb_id"=NULL, "title"='RoboCop', "original_title"='RoboCop', "media_type"='movie', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/gM5ql3BKYmHG3WtZ0buKXN7xY8O.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/xACuC5FwpCdayrcCsJPxYzrl8BO.jpg', "overview"='In RoboCop, the year is 2028 and multinational conglomerate OmniCorp is at the center of robot technology.  Overseas, their drones have been used by the military for years, but have been forbidden for law enforcement in America.  Now OmniCorp wants to bring their controversial technology to the home front, and they see a golden opportunity to do it.  When Alex Murphy – a loving husband, father and good cop doing his best to stem the tide of crime and corruption in Detroit – is critically injured, OmniCorp sees their chance to build a part-man, part-robot police officer.  OmniCorp envisions a RoboCop in every city and even more billions for their shareholders, but they never counted on one thing: there is still a man inside the machine.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.3895, "vote_average"=5.885, "is_ambiguous"=0, "evidence_score"=12.016, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-24 01:47:08' WHERE "id"=1433;
