UPDATE "recommendations" SET "tmdb_id"=10836, "imdb_id"='tt0264508', "igdb_id"=NULL, "title"='Dagon', "original_title"='Dagon', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/8S648eMKObi8ERFS7cSYDocxSaZ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/nO8lpaJLo1UVIXL7eM5ewwudvtY.jpg', "overview"='A boating accident off the coast of Spain sends Paul and his girlfriend Barbara to the decrepit fishing village of Imboca. As night falls, people start to disappear and things not quite human start to appear. Paul is pursued by the entire town. Running for his life, he uncovers Imboca''s secret..they worship Dagon, a monstrous god of the sea...and Dagon''s unholy offspring are on the loose...', "external_url"=NULL, "platforms"=NULL, "popularity"=4.0137, "vote_average"=6.123, "is_ambiguous"=0, "evidence_score"=30.9608, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-24 01:47:08' WHERE "id"=1447;
