UPDATE "recommendations" SET "tmdb_id"=50837, "imdb_id"='tt1441326', "igdb_id"=NULL, "title"='Martha Marcy May Marlene', "original_title"='Martha Marcy May Marlene', "media_type"='movie', "release_year"=2011, "poster_url"='https://image.tmdb.org/t/p/w500/bgB4sa9UfCyGdamfKAZXyEWuAwR.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/eN60BXsEWxFfgatPpYbGMVO5qdM.jpg', "overview"='After several years of living with a cult, Martha finally escapes and calls her estranged sister, Lucy, for help. Martha finds herself at the quiet Connecticut home Lucy shares with her new husband, Ted, but the memories of what she experienced in the cult make peace hard to find. As flashbacks continue to torment her, Martha fails to shake a terrible sense of dread, especially in regard to the cult''s manipulative leader.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.1995, "vote_average"=6.577, "is_ambiguous"=0, "evidence_score"=9.8357142857142854e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-24 01:47:08' WHERE "id"=1449;
