UPDATE "recommendations" SET "tmdb_id"=430214, "imdb_id"='tt6335734', "igdb_id"=NULL, "title"='Night Is Short, Walk On Girl', "original_title"='夜は短し歩けよ乙女', "media_type"='movie', "release_year"=2017, "poster_url"='https://image.tmdb.org/t/p/w500/cDp45WZNqgAli3u4GTnUhsqFn5K.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/iBl3hhtHC7qQX7jGphIAYLpmpPC.jpg', "overview"='As a group of university students go out for a night on the town, a sophomore known only as "The Girl with Black Hair" experiences a series of surreal encounters with the local nightlife – all the while unaware of the romantic longings of "Senpai", a senior student who has been creating increasingly fantastic and contrived reasons to run into her in an effort to win her heart.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.2668, "vote_average"=7.443, "is_ambiguous"=0, "evidence_score"=11.33, "created_at"='2026-07-21 03:32:24', "updated_at"='2026-08-24 01:47:08' WHERE "id"=5015;
UPDATE "recommendations" SET "tmdb_id"=279977, "imdb_id"='tt3547900', "igdb_id"=NULL, "title"='The Mirror', "original_title"='The Mirror', "media_type"='movie', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/n1pUEQuhju702gfA0XGsZz0nBNV.jpg', "backdrop_url"=NULL, "overview"='There is a long-held belief that mirrors act as gateways to another dimension. ·Some also believe the looking glass plays host to a world filled with evil spirits. Such superstition has been the basis for ancient folklore legends about haunting and possession. And one tale about a supposedly haunted mirror was picked up by the media in 2012. Both the Daily Mail and Huffington Post reported on how the owners of a recently purchased antique mirror left them dogged by bad luck, financial misery, strange sightings and death-defying illness. Now writer/director Edward Boase brings that horrifying story to the screen starring Jemma Dallender (I SPIT ON YOUR GRAVE 2), Joshua Dickinson and Nate Fallows (‘Whitechapel’) as flatmates who buy the same eerie antique on ebay and set up round the clock cameras in the hopes of capturing evidence of bumps in the night. You have been warned!', "external_url"=NULL, "platforms"=NULL, "popularity"=1.0065, "vote_average"=4.175, "is_ambiguous"=0, "evidence_score"=9.015, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-24 01:47:08' WHERE "id"=5027;
