UPDATE "recommendations" SET "tmdb_id"=20591, "imdb_id"='tt0291833', "igdb_id"=NULL, "title"='Cradle of Fear', "original_title"='Cradle of Fear', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/qYNYAFCBd83fOAWIIiL4nG6L2zq.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/4m8cK7VfPWn3vnRiwL5JbPUuB5O.jpg', "overview"='A gruesome homage to the cult Amicus anthology Asylum, Cradle of Fear unfolds four screamplays all linked by the unspeakable need of an incarcerated child killer to wreak vengeance on those responsible for his imprisonment. Helped by deranged angel Dani Filth, who leaves a trail of charnel house death in his crimson wake, the cannibal convict forces two Goth vamps to endure a one night stand from hell, two tough female robbers to see through each other, an obscenely rich coke-head to chop up more than a few lines and an internet surfer to descend into madness when he uncovers the ultimate web depravity.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.4105, "vote_average"=4.2, "is_ambiguous"=0, "evidence_score"=6.26, "created_at"='2026-08-03 14:31:56', "updated_at"='2026-08-24 01:47:08' WHERE "id"=6733;
