UPDATE "recommendations" SET "tmdb_id"=236, "imdb_id"='tt0110598', "igdb_id"=NULL, "title"='Muriel''s Wedding', "original_title"='Muriel''s Wedding', "media_type"='movie', "release_year"=1994, "poster_url"='https://image.tmdb.org/t/p/w500/zJyTr8Fo412a2OIfJGXTRAm4IwX.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/x4sqnmV2nAKIG6cmt9WAF9xRA2M.jpg', "overview"='Socially awkward Muriel Heslop wants nothing more than to get married. Unfortunately, due to her oppressive politician father, Muriel has never even been on a date. Ostracized by her more socially adept friends, Muriel runs into fellow outcast Rhonda Epinstalk, and the two move from their small Australian town to the big city of Sydney, where Muriel changes her name and begins the arduous task of redesigning her life to match her fantasies.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.681, "vote_average"=6.831, "is_ambiguous"=0, "evidence_score"=4.025, "created_at"='2026-08-04 03:20:13', "updated_at"='2026-08-24 01:47:08' WHERE "id"=7158;
