UPDATE "recommendations" SET "tmdb_id"=20608, "imdb_id"='tt0130184', "igdb_id"=NULL, "title"='Pervirella', "original_title"='Pervirella', "media_type"='movie', "release_year"=1997, "poster_url"='https://image.tmdb.org/t/p/w500/blclQGN6tsCN3gcwsl7Xxgtwlqm.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/mGFq2RTTh3KdXVjKenzSqN9odCT.jpg', "overview"='This is the story of the beautiful young Pervirella. Set in the mythical English land of Condon, the grotesque, power-mad Queen Victoria builds a wall around the country and establishes a "Monarchy of Terror." Intellectuals and "pervs" are prosecuted and killed, or driven underground to form the "Cult of Perv." Their leader, the Demon Nanny gives birth to a possible savior, then dies. The infant Pervirella grows to maturity with supernatural speed and shows amazing abilities, including raging nymphomania whenever her magical necklace is removed. Pervirella is sought by various rebels, agents of Victoria, the Cult of Perv, and a trio of witches. Eventually she teams up with Amicus Reilly, a James Bond spoof played to stiff, campy perfection by the late David Warbeck. Wild adventures ensue!', "external_url"=NULL, "platforms"=NULL, "popularity"=0.6667, "vote_average"=4.125, "is_ambiguous"=0, "evidence_score"=2.025, "created_at"='2026-08-19 01:49:52', "updated_at"='2026-08-24 01:47:08' WHERE "id"=10557;
